require $GLOBALS['__doc'] . '/content/general_pages/epc_cloudpanel_helpers.php';
$tenants = array('www.epartscart.com', 'epartscart.com', 'www.stylenlook.com');
$src = "server {\n  listen 80;\n  server_name epartscart.com www.stylenlook.com extra.test;\n  return 301 https://www.epartscart.com\$request_uri;\n}\nserver {\n  listen 443 ssl;\n  server_name www.stylenlook.com;\n  ssl_reject_handshake on;\n  return 444;\n}\nserver {\n  listen 443 ssl;\n  server_name keep.test;\n  ssl_reject_handshake on;\n  proxy_pass http://127.0.0.1:3000;\n}\n# EPC_TENANT_DIRECT_START\nserver {\n  server_name www.stylenlook.com;\n  root /old;\n}\n# EPC_TENANT_DIRECT_END\n";
$scrub = epc_clp_vhost_scrub_tenant_misroutes($src, $tenants);
$rejN = 0;
$rej = epc_clp_vhost_strip_ssl_reject_for_hosts($src, $tenants, $rejN);
$n444 = 0; $n3000 = 0;
$stand = epc_clp_vhost_strip_tenant_standalone_blocks($src, $tenants, $n444, $n3000);
$marks = epc_clp_vhost_strip_tenant_markers($src);
$strip = epc_clp_vhost_strip_hosts_from_server_names($src, $tenants, true);
$stripAll = epc_clp_vhost_strip_hosts_from_server_names($src, $tenants, false);
$audit = epc_clp_vhost_audit_server_names($src);
$regs = epc_clp_vhost_protected_regions($src);
$orph = epc_clp_vhost_strip_orphan_tenant_server_blocks($src, $tenants);
return array(
  $scrub,
  $rej,
  $rejN,
  $stand,
  $n444,
  $n3000,
  $marks,
  $strip[0],
  $strip[1],
  $stripAll[0],
  $audit,
  $regs,
  epc_clp_vhost_position_in_regions(0, $regs),
  epc_clp_vhost_position_in_regions($regs[0][0] + 1, $regs),
  $orph['vhost'],
  $orph['removed'],
  $orph['log']
);

require $GLOBALS['__doc'] . '/content/general_pages/epc_cloudpanel_helpers.php';
$cookie = 'sid=1';
$emptySave = epc_clp_vhost_save($cookie, 'www.ecomae.com', '', '');
$emptyPass = epc_clp_nginx_reload_with_pass('');
$emptyGroups = epc_clp_vhost_configure_model_c_tenants($cookie, 'www.ecomae.com', array());
$emptyAlias = epc_clp_vhost_configure_tenant_direct_php($cookie, 'www.ecomae.com', array());
$emptyCreate = epc_clp_web_create_php_site($cookie, array());
return array(
  $emptySave,
  $emptyPass,
  $emptyGroups,
  $emptyAlias,
  $emptyCreate,
  epc_clp_web_site_listed('<div>/site/Foo.Test</div>', 'foo.test'),
  epc_clp_web_site_listed('>Foo.Test<', 'foo.test')
);

require $GLOBALS['__doc'] . '/content/general_pages/epc_cloudpanel_helpers.php';
$doc = $GLOBALS['__doc'] . '/portal';
@mkdir($doc, 0777, true);
$v8080 = "server {\n  listen 8080;\n  server_name www.ecomae.com extra.test;\n}\nserver {\n  listen 80;\n  server_name www.ecomae.com extra.test;\n}\n";
$add = epc_clp_vhost_add_aliases_to_php_backend($v8080, array('www.stylenlook.com', 'extra.test'), 'www.ecomae.com');
$del = epc_clp_vhost_remove_aliases_from_php_backend($add['vhost'], array('www.stylenlook.com', 'extra.test'), 'www.ecomae.com');
$src = "# EPC_TENANT_DIRECT_START\nserver {\n  listen 443 ssl;\n  server_name www.stylenlook.com;\n  {{root}}\n  {{ssl_certificate}}\n  {{ssl_certificate_key}}\n  location ~ \\.php$ {\n    fastcgi_pass 127.0.0.1:9000;\n  }\n}\n# EPC_TENANT_DIRECT_END\nserver {\n  listen 443 ssl;\n  server_name keep.test;\n  ssl_certificate /old.crt;\n}\n";
$root = epc_clp_vhost_patch_tenant_direct_root($src, $doc);
$fail = epc_clp_vhost_patch_failover_splash($src, $doc, array());
$failNamed = epc_clp_vhost_patch_failover_splash($src, $doc, array('keep.test'));
$ssl = epc_clp_vhost_patch_server_ssl_for_hosts($src, array('www.stylenlook.com'), 'www.stylenlook.com', true);
$rm = epc_clp_vhost_remove_server_blocks_for_hosts($src, array('keep.test'));
$emptyFail = epc_clp_vhost_patch_failover_splash($src, '', array('www.stylenlook.com'));
$rootNorm = str_replace($doc, 'DOCROOT', $root);
return array(
  $add['vhost'],
  $add['log'],
  $del['vhost'],
  $del['log'],
  $rootNorm,
  $fail['patched'],
  $fail['log'],
  substr_count($fail['vhost'], 'epc-platform-splash.html'),
  $failNamed['patched'],
  $ssl['patched'],
  $ssl['log'],
  strpos($ssl['vhost'], '/etc/nginx/ssl-certificates/www.stylenlook.com.crt') !== false,
  $rm['removed'],
  $rm['log'],
  $emptyFail
);
